import re

def update_poi_file(file_path, updates):
    with open(file_path, 'r', encoding='utf-8') as f:
        content = f.read()

    for poi_id, hu_desc, hu_facts in updates:
        # Search for the POI block by ID
        # Then replace the empty hu fields inside that block
        start_search = content.find(f'id: "{poi_id}"')
        if start_search == -1:
            print(f"Warning: POI {poi_id} not found.")
            continue
            
        # Find descriptionAdvanced block after the ID
        desc_start = content.find("descriptionAdvanced:", start_search)
        hu_desc_start = content.find('hu: ""', desc_start)
        if hu_desc_start != -1:
            content = content[:hu_desc_start + 4] + hu_desc + content[hu_desc_start + 6:]
            
        # Find factsAdvanced block after the ID
        facts_start = content.find("factsAdvanced:", start_search)
        hu_facts_start = content.find('hu: []', facts_start)
        if hu_facts_start != -1:
            content = content[:hu_facts_start + 4] + hu_facts + content[hu_facts_start + 6:]

    with open(file_path, 'w', encoding='utf-8') as f:
        f.write(content)

